 "content": "def transform(grid):
    """Fill any all-zero row with the color of the last nonzero row."""
    out = [row[:] for row in grid]
    nonzero_rows = [row for row in grid if any(value != 0 for value in row)]
    if not nonzero_rows:
        return out
    color = nonzero_rows[-1][0]
    for i, row in enumerate(out):
        if all(value == 0 for value in row):
            out[i] = [color] * len(row)
    return out
